import{_ as e,o as n,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Jewel -- RGW Multitenancy","description":"","frontmatter":{"title":"CDS Jewel -- RGW Multitenancy","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-03T00:00:00.000Z","tags":["Ceph","RGW","Multitenancy","Keystone","Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_RGW_Multitenancy.md","filePath":"posts/2015/CDS_Jewel_--_RGW_Multitenancy.md","lastUpdated":1780459816000}'),o={name:"posts/2015/CDS_Jewel_--_RGW_Multitenancy.md"};function i(r,t,a,_,p,g){return n(),l("div",null,[...t[0]||(t[0]=[s("<p>在Ceph的RGW（Rados Gateway）多租户功能的讨论中，参会人员探讨了如何实现和优化这一功能。</p><p><strong>主要议题</strong>：</p><ul><li><strong>多租户需求</strong>： 当前RGW类似于S3，只有一个全局用户名空间。新方案需支持独立租户，每个租户拥有独立命名空间、用户和存储桶。</li><li><strong>实现方案</strong>： 修改数据结构和API，引入租户实体，支持独立配置和权限控制。</li><li><strong>与Keystone集成</strong>： 利用Keystone的租户概念，实现高级多租户功能，考虑现有系统兼容性。</li></ul><p><strong>讨论细节</strong>：</p><ul><li><strong>数据结构修改</strong>： 将存储桶和用户标识符从字符串改为结构体，以便区分不同租户。</li><li><strong>租户实体创建</strong>： 为每个租户创建租户实体，存储租户信息，如默认放置目标、配额、DNS名称等。</li><li><strong>数据访问权限</strong>： 考虑不同租户之间的数据访问权限和统计信息收集。</li><li><strong>Keystone集成</strong>： 将Keystone租户映射到RGW租户，实现更高级别的多租户功能。</li></ul><p><strong>行动计划</strong>：</p><ul><li>评估现有代码库，确定修改范围和所需工作量。</li><li>设计新的数据结构和API。</li><li>修改对象类和网关构建中的代码。</li><li>实现租户实体和相关的管理功能。</li><li>考虑Keystone集成方案。</li></ul><p>通过这次会议，Ceph团队明确了RGW多租户功能的实现路径，为提高系统灵活性和安全性奠定了基础。</p>",8)])])}const d=e(o,[["render",i]]);export{u as __pageData,d as default};
